def test_summary_is_zero_for_empty_shop(shop):
    response = shop.fulfilment.handle_fulfilment_summary()
    assert response.status == 200
    assert response.body == {"open_orders": 0, "units_to_pick": 0, "low_stock_products": 0}


def test_summary_counts_open_orders_and_units(shop):
    shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "BOOK", "quantity": 2}]})
    shop.orders.handle_create({"customer_id": "c2", "items": [
        {"sku": "PEN", "quantity": 3}, {"sku": "BOOK", "quantity": 1}]})
    assert shop.fulfilment.handle_fulfilment_summary().body == {
        "open_orders": 2, "units_to_pick": 6, "low_stock_products": 0}


def test_summary_excludes_cancelled_orders(shop):
    cancelled = shop.orders.handle_create(
        {"customer_id": "c1", "items": [{"sku": "BOOK", "quantity": 4}]}).body["order_id"]
    shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 1}]})
    shop.orders.handle_cancel(cancelled)
    assert shop.fulfilment.handle_fulfilment_summary().body == {
        "open_orders": 1, "units_to_pick": 1, "low_stock_products": 0}


def test_low_stock_line_is_five_units_exclusive(shop):
    # LAMP starts with 5 on hand: not below the line yet.
    assert shop.fulfilment.handle_fulfilment_summary().body["low_stock_products"] == 0
    shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "LAMP", "quantity": 1}]})
    assert shop.fulfilment.handle_fulfilment_summary().body["low_stock_products"] == 1

